-- Actual targeted UB view definitions; migration script owns backup/transaction.

CREATE VIEW "clean_ub_a_standardized" AS SELECT c.*,c.id_penghubung AS assignment_id FROM "clean_ub_a" c;

CREATE VIEW "clean_ub_b_standardized" AS SELECT c.*,c.id_penghubung AS assignment_id FROM "clean_ub_b" c;

CREATE VIEW "clean_ub_c_standardized" AS SELECT c.*,c.id_penghubung AS assignment_id FROM "clean_ub_c" c;

CREATE VIEW "mart_ub_a" AS SELECT c.*,f.batch_id AS __batch_id,f.sha256 AS __source_sha256
            FROM "clean_ub_a_standardized" c JOIN active_imports a ON a.source_id='ub_a' AND a.import_id=c.__import_id
            JOIN imported_files f ON f.import_id=c.__import_id;

CREATE VIEW "mart_ub_b" AS SELECT c.*,f.batch_id AS __batch_id,f.sha256 AS __source_sha256
            FROM "clean_ub_b_standardized" c JOIN active_imports a ON a.source_id='ub_b' AND a.import_id=c.__import_id
            JOIN imported_files f ON f.import_id=c.__import_id;

CREATE VIEW "mart_ub_c" AS SELECT c.*,f.batch_id AS __batch_id,f.sha256 AS __source_sha256
            FROM "clean_ub_c_standardized" c JOIN active_imports a ON a.source_id='ub_c' AND a.import_id=c.__import_id
            JOIN imported_files f ON f.import_id=c.__import_id;

CREATE VIEW mart_ub_integrated AS SELECT m.assignment_id,a."__row_id",a."__import_id",a."__clean_hash",a."__key",a."__version_normalized",a."__key_valid",a."__conflict",a."id_penghubung",a."nama_usaha",a."nama_komersial",a."status_keberadaan",a."kode_desa",a."kecamatan",a."desa_kelurahan",a."alamat_usaha",a."link_google_maps",a."id_sbr",a."nib",a."badan_usaha",a."kbli_akhir",a."kategori_kbli",a."kegiatan_utama",a."produk_utama",a."jaringan_usaha",a."nama_kantor_pusat",a."alamat_kantor_pusat",a."nama_penanggung_jawab",a."nik_penanggung_jawab",a."jenis_kelamin_penanggung_jawab",a."umur_penanggung_jawab",a."nomor_hp_usaha",a."email_usaha",a."__batch_id",a."__source_sha256",'ASSIGNMENT_KEY_VERIFIED' AS integration_status,'QUESTIONNAIRE_VERSION_NOT_VERIFIED' AS questionnaire_version_status,m."assignment_date_modified" AS "assignment_ub__assignment_date_modified",m."code_identity" AS "assignment_ub__code_identity",m."listing_assignment" AS "assignment_ub__listing_assignment",m."mode" AS "assignment_ub__mode",m."status_assignment" AS "assignment_ub__status_assignment",m."kode_status_assignment" AS "assignment_ub__kode_status_assignment",m."tanggal_dibuat" AS "assignment_ub__tanggal_dibuat",m."tanggal_diubah" AS "assignment_ub__tanggal_diubah",m."done" AS "assignment_ub__done",m."external_done" AS "assignment_ub__external_done",m."source_from" AS "assignment_ub__source_from",m."kode_kabupaten" AS "assignment_ub__kode_kabupaten",m."kode_kecamatan" AS "assignment_ub__kode_kecamatan",m."kecamatan" AS "assignment_ub__kecamatan",m."kode_desa" AS "assignment_ub__kode_desa",m."desa_kelurahan" AS "assignment_ub__desa_kelurahan",m."kode_sls" AS "assignment_ub__kode_sls",m."sls" AS "assignment_ub__sls",m."kode_subsls" AS "assignment_ub__kode_subsls",m."subsls" AS "assignment_ub__subsls",m."latitude_assignment" AS "assignment_ub__latitude_assignment",m."longitude_assignment" AS "assignment_ub__longitude_assignment",m."versi_root_terbaru" AS "assignment_ub__versi_root_terbaru",m."status_kuesioner" AS "assignment_ub__status_kuesioner",m."__source_sha256" AS "assignment_ub__source_sha256",m."__batch_id" AS "assignment_ub__batch_id",m."__row_id" AS "assignment_ub__row_id",m."__import_id" AS "assignment_ub__import_id",b."tahun_operasi" AS "ub_b__tahun_operasi",b."pekerja_laki_laki" AS "ub_b__pekerja_laki_laki",b."pekerja_perempuan" AS "ub_b__pekerja_perempuan",b."jumlah_pekerja" AS "ub_b__jumlah_pekerja",b."pendapatan_utama" AS "ub_b__pendapatan_utama",b."pendapatan_lainnya" AS "ub_b__pendapatan_lainnya",b."total_pendapatan" AS "ub_b__total_pendapatan",b."gaji_dan_jaminan_sosial" AS "ub_b__gaji_dan_jaminan_sosial",b."biaya_produksi" AS "ub_b__biaya_produksi",b."biaya_pembelian_barang" AS "ub_b__biaya_pembelian_barang",b."biaya_operasional" AS "ub_b__biaya_operasional",b."biaya_non_operasional" AS "ub_b__biaya_non_operasional",b."total_pengeluaran" AS "ub_b__total_pengeluaran",b."memiliki_catatan_keuangan" AS "ub_b__memiliki_catatan_keuangan",b."aset_tanah_bangunan" AS "ub_b__aset_tanah_bangunan",b."aset_selain_tanah_bangunan" AS "ub_b__aset_selain_tanah_bangunan",b."total_aset" AS "ub_b__total_aset",b."luas_tanah_m2" AS "ub_b__luas_tanah_m2",b."modal_pribadi_persen" AS "ub_b__modal_pribadi_persen",b."modal_nonprofit_persen" AS "ub_b__modal_nonprofit_persen",b."modal_korporasi_publik_persen" AS "ub_b__modal_korporasi_publik_persen",b."modal_korporasi_nonpublik_persen" AS "ub_b__modal_korporasi_nonpublik_persen",b."modal_pemerintah_persen" AS "ub_b__modal_pemerintah_persen",b."modal_asing_persen" AS "ub_b__modal_asing_persen",b."__source_sha256" AS "ub_b__source_sha256",b."__batch_id" AS "ub_b__batch_id",b."__row_id" AS "ub_b__row_id",b."__import_id" AS "ub_b__import_id",c."negara_kantor_pusat" AS "ub_c__negara_kantor_pusat",c."jumlah_kantor_cabang" AS "ub_c__jumlah_kantor_cabang",c."jenis_kawasan" AS "ub_c__jenis_kawasan",c."nama_kawasan" AS "ub_c__nama_kawasan",c."nama_kek_ki" AS "ub_c__nama_kek_ki",c."memiliki_nib" AS "ub_c__memiliki_nib",c."alasan_tanpa_nib" AS "ub_c__alasan_tanpa_nib",c."produk_bersertifikat_halal" AS "ub_c__produk_bersertifikat_halal",c."memiliki_izin_edar" AS "ub_c__memiliki_izin_edar",c."website" AS "ub_c__website",c."menggunakan_internet" AS "ub_c__menggunakan_internet",c."internet_pesanan" AS "ub_c__internet_pesanan",c."internet_produksi" AS "ub_c__internet_produksi",c."internet_distribusi" AS "ub_c__internet_distribusi",c."internet_pembelian" AS "ub_c__internet_pembelian",c."internet_promosi" AS "ub_c__internet_promosi",c."persentase_pendapatan_online" AS "ub_c__persentase_pendapatan_online",c."memanfaatkan_teknologi_digital" AS "ub_c__memanfaatkan_teknologi_digital",c."produksi_barang_di_lokasi" AS "ub_c__produksi_barang_di_lokasi",c."menghasilkan_produk_ramah_lingkungan" AS "ub_c__menghasilkan_produk_ramah_lingkungan",c."perlindungan_lingkungan" AS "ub_c__perlindungan_lingkungan",c."penggunaan_produk_seni_budaya" AS "ub_c__penggunaan_produk_seni_budaya",c."kemitraan_kdkmp" AS "ub_c__kemitraan_kdkmp",c."keterlibatan_mbg" AS "ub_c__keterlibatan_mbg",c."__source_sha256" AS "ub_c__source_sha256",c."__batch_id" AS "ub_c__batch_id",c."__row_id" AS "ub_c__row_id",c."__import_id" AS "ub_c__import_id",(m.__row_id IS NOT NULL) AS "has_assignment_ub",(a.__row_id IS NOT NULL) AS "has_ub_a",(b.__row_id IS NOT NULL) AS "has_ub_b",(c.__row_id IS NOT NULL) AS "has_ub_c" FROM mart_assignment_ub m LEFT JOIN mart_ub_a a ON m.assignment_id=a.assignment_id LEFT JOIN mart_ub_b b ON m.assignment_id=b.assignment_id LEFT JOIN mart_ub_c c ON m.assignment_id=c.assignment_id;
